// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;

    function setUp() public { c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0)); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // current owner (deployer of c in setUp) transfers ownership to the fuzzed address
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        // Rule: for every admissible input, ownership is transferred to the ARGUMENT address.
        assertTrue(c.owner() == newOwner, "owner must be the requested newOwner");
    }
}
